  KEY `idx_kb_created` (`knowledge_base_id`,`created_at`),
  CONSTRAINT `fk_qlog_kb` FOREIGN KEY (`knowledge_base_id`) REFERENCES `know_bases` (`id`) ON DELETE CASCADE
